public string ToString(string? format, IFormatProvider? formatProvider = null)
{
    format ??= "0.## ";
    formatProvider ??= CultureInfo.CurrentCulture;

    if (!format.Contains('#') && !format.Contains('0'))
    {
        format = "0.## " + format;
    }

    if (format.Contains("#.##"))
    {
        format = format.Replace("#.##", "0.##");
    }

    var culture = formatProvider as CultureInfo ?? CultureInfo.CurrentCulture;
    var compareInfo = culture.CompareInfo;

    if (TryFormatUnit(format, compareInfo, TerabyteSymbol, Terabytes, formatProvider, out var result)) return result;
    if (TryFormatUnit(format, compareInfo, GigabyteSymbol, Gigabytes, formatProvider, out result)) return result;
    if (TryFormatUnit(format, compareInfo, MegabyteSymbol, Megabytes, formatProvider, out result)) return result;
    if (TryFormatUnit(format, compareInfo, KilobyteSymbol, Kilobytes, formatProvider, out result)) return result;

    if (format.Contains(ByteSymbol, StringComparison.Ordinal))
        return Bytes.ToString(format, formatProvider);

    if (format.Contains(BitSymbol, StringComparison.Ordinal))
        return ((double)Bits).ToString(format, formatProvider);

    var (value, symbol) = GetLargestWholeNumber();
    return $"{value.ToString(format, formatProvider)} {symbol}";
}

private static bool TryFormatUnit(
    string format, CompareInfo compareInfo, string symbol, double value,
    IFormatProvider formatProvider, out string result)
{
    if (compareInfo.IndexOf(format, symbol, CompareOptions.IgnoreCase) != -1)
    {
        result = value.ToString(format, formatProvider);
        return true;
    }

    result = "";
    return false;
}

